function searchPicker(label,name,items,onPick){const wrap=document.createElement('label');wrap.className='relative text-sm font-bold';wrap.innerHTML=`${label}<input type="hidden" name="${name}"><input type="search" autocomplete="off" placeholder="Rechercher…" class="mt-1 w-full rounded-xl border px-3 py-3"><div class="absolute left-0 right-0 top-full z-20 mt-1 hidden max-h-48 overflow-y-auto rounded-xl border bg-white p-1 shadow-xl"></div>`;const hidden=wrap.querySelector('input[type=hidden]'),input=wrap.querySelector('input[type=search]'),list=wrap.querySelector('div');let current=items;const render=()=>{const q=input.value.toLowerCase();list.innerHTML=current.filter(x=>!q||x.label.toLowerCase().includes(q)).slice(0,40).map(x=>`<button type="button" data-id="${x.id}" class="block w-full rounded-lg px-3 py-2 text-left font-medium hover:bg-indigo-50">${esc(x.label)}</button>`).join('')||'<span class="block p-3 text-xs text-slate-500">Aucun résultat</span>';list.classList.remove('hidden');list.querySelectorAll('button').forEach(b=>b.onclick=()=>{const item=current.find(x=>String(x.id)===b.dataset.id);hidden.value=b.dataset.id;input.value=item?.label||'';list.classList.add('hidden');onPick?.(item)});};input.onfocus=render;input.oninput=()=>{hidden.value='';render()};wrap.addEventListener('focusout',()=>setTimeout(()=>{if(!wrap.contains(document.activeElement))list.classList.add('hidden')},120));wrap.setItems=next=>{current=next;hidden.value='';input.value=''};return wrap}
