document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const key=b.dataset.detail,t=treasuryData.totals;let title='',rows=[],intro='';if(key==='available'){const a=treasuryData.availableBreakdown;title='Disponible du jour';intro=`Situation initiale : <b>${money(a.opening)}</b><br>+ Entrées manuelles réalisées : <b>${money(a.manual_real_in)}</b><br>− Sorties manuelles réalisées : <b>${money(a.manual_real_out)}</b><br>− Fiches décaissées : <b>${money(a.fiche_real_out)}</b><hr class="my-2 border-indigo-200">Disponible : <b>${money(treasuryData.available)}</b>`;rows=treasuryData.paidFichesPeriod.map(r=>row(r,'Fiche décaissée'));}else if(key==='projected'){title='Disponible prévisionnel';intro=`Disponible actuel ${money(treasuryData.available)} + entrées prévues ${money(t.forecast_in)} − sorties prévues ${money(t.forecast_out)}`;rows=[...manual('in','forecast').map(r=>row(r,'Entrée prévue')),...manual('out','forecast').map(r=>row(r,'Sortie prévue')),...treasuryData.plannedFichesPeriod.map(r=>row(r,'Fiche prévue'))];}else{const map={'real-in':['Entrées réelles','in','real'],'forecast-in':['Entrées prévisionnelles','in','forecast'],'real-out':['Sorties réelles','out','real'],'forecast-out':['Sorties prévisionnelles','out','forecast']},m=map[key];title=m[0];rows=manual(m[1],m[2]).map(r=>row(r,m[0]));if(key==='real-out')rows.push(...treasuryData.paidFichesPeriod.map(r=>row(r,'Fiche décaissée')));if(key==='forecast-out')rows.push(...treasuryData.plannedFichesPeriod.map(r=>row(r,'Fiche prévue')))}document.getElementById('detailTitle').textContent=title;document.getElementById('detailContent').innerHTML=(intro?`<div class="mb-4 rounded-2xl bg-indigo-50 p-4 text-sm text-indigo-950">${intro}</div>`:'')+(rows.join('')||'<div class="py-12 text-center text-slate-500">Aucun mouvement dans cette rubrique.</div>');open('detailModal')});
const flowLabel=r=>r.assignment_label||[r.chantier_code,r.chantier_title,r.ligne_devis_label].filter(Boolean).join(' · ')||'Sans affectation',beneficiaryLabel=r=>r.beneficiary||'Bénéficiaire non renseigné',requesterLabel=r=>r.requester_name||'Demandeur non renseigné';
const profileUrl=path=>{path=String(path||'').trim();return !path?'':/^https?:\/\//.test(path)||path.startsWith('/')?path:'../'+path.replace(/^\.\//,'')},initials=name=>String(name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase(),avatar=(path,name,size='h-7 w-7')=>path?`<img src="${esc(profileUrl(path))}" alt="" class="${size} rounded-full border-2 border-white object-cover shadow">`:`<span class="${size} grid place-items-center rounded-full bg-slate-200 text-[10px] font-black text-slate-600">${esc(initials(name))}</span>`,personBadge=(role,name,photo,phone,color)=>{if(!name)return'';const palette={emerald:['#ecfdf5','#a7f3d0','#047857'],indigo:['#eef2ff','#c7d2fe','#4338ca'],amber:['#fffbeb','#fde68a','#b45309']}[color]||['#f8fafc','#e2e8f0','#475569'];return`<span class="inline-flex items-center gap-2 rounded-full border py-1 pl-1 pr-3" style="background:${palette[0]};border-color:${palette[1]}">${avatar(photo,name)}<span><b class="block text-[9px] uppercase tracking-wide" style="color:${palette[2]}">${esc(role)}</b><span class="block text-[11px] font-bold text-slate-800">${esc(name)}</span>${phone?`<small class="block text-[9px] text-slate-500">${esc(phone)}</small>`:''}</span></span>`};
function flowRow(r){const incoming=r.direction==='in',category=treasuryCatalogs.entry_categories?.[r.entry_category]||'',meta=[r.reference,category,flowLabel(r)].filter(Boolean).join(' · '),people=[personBadge('Bénéficiaire · '+(r.beneficiary_type||'Non typé'),r.beneficiary,r.beneficiary_photo,r.beneficiary_phone,'emerald'),personBadge('Demandeur',r.requester_name,r.requester_photo,r.requester_phone,'indigo'),personBadge('Contestataire retenu',r.challenger_name,r.challenger_photo,r.challenger_phone,'amber')].filter(Boolean).join('');return `<article class="treasury-flow-row"><span class="treasury-flow-icon ${incoming?'in':'out'}"><i class="fas ${incoming?'fa-arrow-down':'fa-arrow-up'}"></i></span><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><strong class="truncate text-slate-950">${esc(r.label||'Mouvement')}</strong><span class="rounded-full px-2 py-1 text-[10px] font-black uppercase ${incoming?'bg-emerald-50 text-emerald-700':'bg-rose-50 text-rose-700'}">${incoming?'Entrée':'Sortie'}</span></div><small class="mt-1 block truncate text-slate-500">${esc(meta)} · ${esc(new Date((r.movement_date||'')+'T00:00:00').toLocaleDateString('fr-FR'))}</small>${people?`<div class="mt-2 flex flex-wrap gap-2">${people}</div>`:''}</div><strong class="treasury-flow-amount text-right text-base ${incoming?'text-emerald-700':'text-rose-700'}">${incoming?'+':'−'} ${money(r.amount)}</strong></article>`}
function detailDataset(key){const t=treasuryData.totals;if(key==='available')return{title:'Disponible du jour',rows:[],context:`Montant déclaré et figé aujourd’hui : ${money(treasuryData.available)}. Les décaissements n’en modifient pas la valeur ; ils sont enregistrés séparément dans les sorties et le solde réels.`};if(key==='projected')return{title:'Disponible prévisionnel',rows:[...manual('in','forecast'),...manual('out','forecast'),...treasuryData.plannedFichesPeriod.map(r=>({...r,direction:'out'}))],context:`Disponible déclaré ${money(treasuryData.available)} · projection nette ${money(t.projected_available)}`};const map={'real-in':['Entrées réelles','in','real'],'forecast-in':['Entrées prévisionnelles','in','forecast'],'real-out':['Sorties réelles','out','real'],'forecast-out':['Sorties prévisionnelles','out','forecast']},m=map[key],rows=manual(m[1],m[2]);if(key==='real-out')rows.push(...treasuryData.paidFichesPeriod.map(r=>({...r,direction:'out'})));if(key==='forecast-out')rows.push(...treasuryData.plannedFichesPeriod.map(r=>({...r,direction:'out'})));return{title:m[0],rows,context:'Période du <?=date('d/m/Y',strtotime($from))?> au <?=date('d/m/Y',strtotime($to))?>'}}
function renderFlowAnalysis(dataset,mode='list'){const rows=dataset.rows||[],incoming=rows.filter(r=>r.direction==='in').reduce((s,r)=>s+Number(r.amount||0),0),outgoing=rows.filter(r=>r.direction!=='in').reduce((s,r)=>s+Number(r.amount||0),0),net=incoming-outgoing;let groups;if(mode==='list')groups=new Map([['Tous les mouvements',rows]]);else{const getter=mode==='allocation'?flowLabel:mode==='beneficiary'?beneficiaryLabel:requesterLabel;groups=new Map;rows.forEach(r=>{const key=getter(r);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)})}const bodies=[...groups].map(([label,items])=>{const subtotal=items.reduce((s,r)=>s+(r.direction==='in'?1:-1)*Number(r.amount||0),0);return `<section class="treasury-group"><header class="treasury-group-head"><div><strong class="text-slate-950">${esc(label)}</strong><small class="ml-2 text-slate-400">${items.length} mouvement${items.length>1?'s':''}</small></div><strong class="${subtotal>=0?'text-emerald-700':'text-rose-700'}">${subtotal>=0?'+':'−'} ${money(Math.abs(subtotal))}</strong></header><div class="treasury-group-body">${items.map(flowRow).join('')}</div></section>`}).join('');document.getElementById('detailContent').innerHTML=`<div class="sticky top-0 z-10 -mx-5 -mt-5 mb-5 border-b bg-white/95 p-5 backdrop-blur"><div class="grid gap-3 lg:grid-cols-[1fr_auto]"><div><p class="text-sm text-slate-500">${esc(dataset.context)}</p><div class="mt-3 flex flex-wrap gap-2" data-group-tabs>${[['list','Affichage liste'],['allocation','Par affectation'],['beneficiary','Par bénéficiaire'],['requester','Par demandeur']].map(([v,l])=>`<button data-mode="${v}" class="rounded-full px-3 py-2 text-xs font-black ${v===mode?'bg-indigo-700 text-white':'bg-slate-100 text-slate-600'}">${l}</button>`).join('')}</div></div><div class="grid grid-cols-3 gap-2 text-right"><div class="rounded-xl bg-emerald-50 p-3"><small class="text-emerald-700">Entrées</small><strong class="block text-emerald-800">${money(incoming)}</strong></div><div class="rounded-xl bg-rose-50 p-3"><small class="text-rose-700">Sorties</small><strong class="block text-rose-800">${money(outgoing)}</strong></div><div class="rounded-xl bg-indigo-50 p-3"><small class="text-indigo-700">Total général net</small><strong class="block ${net>=0?'text-emerald-800':'text-rose-800'}">${money(net)}</strong></div></div></div></div><div class="grid gap-4">${bodies||'<div class="rounded-2xl bg-white py-14 text-center text-slate-500">Aucun mouvement dans cette rubrique.</div>'}</div>`;document.querySelectorAll('[data-group-tabs] button').forEach(button=>button.onclick=()=>renderFlowAnalysis(dataset,button.dataset.mode))}
function exportTreasuryCsv(dataset,rows){const fields=['Date','Sens','Libellé','Référence','Affectation','Bénéficiaire','Demandeur','Montant'];const values=rows.map(r=>[r.movement_date,r.direction==='in'?'Entrée':'Sortie',r.label||'',r.reference||'',flowLabel(r),beneficiaryLabel(r),requesterLabel(r),Number(r.amount||0)]),quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"',csv='\uFEFF'+[fields,...values].map(line=>line.map(quote).join(';')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='tresorerie_'+dataset.title.toLowerCase().replace(/[^a-z0-9]+/gi,'_')+'_<?=date('Ymd')?>.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function renderTreasuryAnalysis(dataset,mode='list',filters={allocation:'',beneficiary:''}){const allocations=[...new Set(dataset.rows.map(flowLabel))].sort(),beneficiaries=[...new Set(dataset.rows.map(beneficiaryLabel))].sort(),rows=dataset.rows.filter(r=>(!filters.allocation||flowLabel(r)===filters.allocation)&&(!filters.beneficiary||beneficiaryLabel(r)===filters.beneficiary)),incoming=rows.filter(r=>r.direction==='in').reduce((s,r)=>s+Number(r.amount||0),0),outgoing=rows.filter(r=>r.direction!=='in').reduce((s,r)=>s+Number(r.amount||0),0),net=incoming-outgoing,getter=mode==='allocation'?flowLabel:mode==='beneficiary'?beneficiaryLabel:mode==='requester'?requesterLabel:null,groups=new Map;if(!getter)groups.set('Tous les mouvements',rows);else rows.forEach(r=>{const key=getter(r);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)});const bodies=[...groups].map(([label,items])=>{const subtotal=items.reduce((s,r)=>s+(r.direction==='in'?1:-1)*Number(r.amount||0),0),sample=items[0]||{},identity=mode==='beneficiary'?`<div class="flex items-center gap-3">${avatar(sample.beneficiary_photo,label,'h-12 w-12')}<div><span class="rounded-full bg-emerald-100 px-2 py-1 text-[9px] font-black uppercase text-emerald-800">Bénéficiaire · ${esc(sample.beneficiary_type||'Non typé')}</span><strong class="mt-1 block">${esc(label)}</strong>${sample.beneficiary_phone?`<small class="text-slate-500"><i class="fas fa-phone mr-1"></i>${esc(sample.beneficiary_phone)}</small>`:''}</div></div>`:mode==='requester'?`<div class="flex items-center gap-3">${avatar(sample.requester_photo,label,'h-12 w-12')}<div><span class="rounded-full bg-indigo-100 px-2 py-1 text-[9px] font-black uppercase text-indigo-800">Demandeur</span><strong class="mt-1 block">${esc(label)}</strong>${sample.requester_phone?`<small class="text-slate-500"><i class="fas fa-phone mr-1"></i>${esc(sample.requester_phone)}</small>`:''}</div></div>`:`<div><strong>${esc(label)}</strong><small class="ml-2 text-slate-400">${items.length} mouvement${items.length>1?'s':''}</small></div>`;return `<section class="treasury-group"><header class="treasury-group-head">${identity}<div class="text-right"><small class="block text-slate-400">${items.length} mouvement${items.length>1?'s':''}</small><strong class="${subtotal>=0?'text-emerald-700':'text-rose-700'}">${subtotal>=0?'+':'−'} ${money(Math.abs(subtotal))}</strong></div></header><div class="treasury-group-body">${items.map(flowRow).join('')}</div></section>`}).join('');document.getElementById('detailContent').innerHTML=`<div class="sticky top-0 z-10 -mx-5 -mt-5 mb-5 border-b bg-white/95 p-5 backdrop-blur"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-sm text-slate-500">${esc(dataset.context)}</p><div class="mt-3 flex flex-wrap gap-2" data-group-tabs>${[['list','Liste'],['allocation','Par affectation'],['beneficiary','Par bénéficiaire'],['requester','Par demandeur']].map(([v,l])=>`<button data-mode="${v}" class="rounded-full px-3 py-2 text-xs font-black ${v===mode?'bg-indigo-700 text-white':'bg-slate-100 text-slate-600'}">${l}</button>`).join('')}</div></div><button data-export-view class="rounded-xl bg-slate-950 px-4 py-3 text-sm font-black text-white"><i class="fas fa-file-excel mr-2 text-emerald-400"></i>Exporter la vue</button></div><div class="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-[1fr_1fr_150px_150px_170px]"><label class="text-xs font-bold text-slate-500">Affectation<select data-filter-allocation class="mt-1 w-full rounded-xl border px-3 py-2"><option value="">Toutes les affectations</option>${allocations.map(v=>`<option ${v===filters.allocation?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="text-xs font-bold text-slate-500">Bénéficiaire<select data-filter-beneficiary class="mt-1 w-full rounded-xl border px-3 py-2"><option value="">Tous les bénéficiaires</option>${beneficiaries.map(v=>`<option ${v===filters.beneficiary?'selected':''}>${esc(v)}</option>`).join('')}</select></label><div class="rounded-xl bg-emerald-50 p-3 text-right"><small>Entrées</small><strong class="block text-emerald-800">${money(incoming)}</strong></div><div class="rounded-xl bg-rose-50 p-3 text-right"><small>Sorties</small><strong class="block text-rose-800">${money(outgoing)}</strong></div><div class="rounded-xl bg-indigo-50 p-3 text-right"><small>Total général net</small><strong class="block ${net>=0?'text-emerald-800':'text-rose-800'}">${money(net)}</strong></div></div></div><div class="grid gap-4">${bodies||'<div class="rounded-2xl bg-white py-14 text-center text-slate-500">Aucun résultat pour ces filtres.</div>'}</div>`;document.querySelectorAll('[data-group-tabs] button').forEach(b=>b.onclick=()=>renderTreasuryAnalysis(dataset,b.dataset.mode,filters));document.querySelector('[data-filter-allocation]').onchange=e=>renderTreasuryAnalysis(dataset,mode,{...filters,allocation:e.target.value});document.querySelector('[data-filter-beneficiary]').onchange=e=>renderTreasuryAnalysis(dataset,mode,{...filters,beneficiary:e.target.value});document.querySelector('[data-export-view]').onclick=()=>exportTreasuryCsv(dataset,rows)}
document.querySelectorAll('[data-detail]').forEach(button=>button.onclick=()=>{const dataset=detailDataset(button.dataset.detail);document.getElementById('detailTitle').textContent=dataset.title;renderTreasuryAnalysis(dataset);open('detailModal')});
</script>
<script>
(()=>{const uniq=(rows,getter)=>[...new Set(rows.map(getter))].sort(),selected=(filters,key)=>filters[key]||[],matches=(value,values)=>!values.length||values.includes(value);
function multiPicker(label,key,options,values){return `<div class="rounded-2xl border bg-white p-2" data-multi-filter="${key}"><span class="text-[10px] font-black uppercase tracking-wide text-slate-500">${label}</span><div class="mt-1 flex min-h-9 flex-wrap items-center gap-1">${values.map(v=>`<button type="button" data-remove="${encodeURIComponent(v)}" class="rounded-full bg-indigo-100 px-2 py-1 text-[10px] font-bold text-indigo-800">${esc(v)} ×</button>`).join('')}<input type="search" list="filter-${key}" placeholder="Rechercher…" class="min-w-[130px] flex-1 border-0 p-1 text-xs outline-none"><datalist id="filter-${key}">${options.filter(v=>!values.includes(v)).map(v=>`<option value="${esc(v)}">`).join('')}</datalist></div></div>`}
function renderMulti(dataset,mode='list',filters={allocation:[],beneficiary:[],requester:[]}){const all=dataset.rows||[],options={allocation:uniq(all,flowLabel),beneficiary:uniq(all,beneficiaryLabel),requester:uniq(all,requesterLabel)},rows=all.filter(r=>matches(flowLabel(r),selected(filters,'allocation'))&&matches(beneficiaryLabel(r),selected(filters,'beneficiary'))&&matches(requesterLabel(r),selected(filters,'requester'))),incoming=rows.filter(r=>r.direction==='in').reduce((s,r)=>s+Number(r.amount||0),0),outgoing=rows.filter(r=>r.direction!=='in').reduce((s,r)=>s+Number(r.amount||0),0),getter=mode==='allocation'?flowLabel:mode==='beneficiary'?beneficiaryLabel:mode==='requester'?requesterLabel:()=> 'Tous les mouvements',groups=new Map;rows.forEach(r=>{const k=getter(r);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r)});const sections=[...groups].map(([label,items])=>{const subtotal=items.reduce((s,r)=>s+(r.direction==='in'?1:-1)*Number(r.amount||0),0),sample=items[0]||{},identity=mode==='beneficiary'?`${avatar(sample.beneficiary_photo,label,'h-12 w-12')}<div><span class="rounded-full bg-emerald-100 px-2 py-1 text-[9px] font-black uppercase text-emerald-800">Bénéficiaire · ${esc(sample.beneficiary_type||'Non typé')}</span><strong class="mt-1 block">${esc(label)}</strong><small class="text-slate-500">${esc(sample.beneficiary_phone||'Téléphone non renseigné')}</small></div>`:mode==='requester'?`${avatar(sample.requester_photo,label,'h-12 w-12')}<div><span class="rounded-full bg-indigo-100 px-2 py-1 text-[9px] font-black uppercase text-indigo-800">Demandeur</span><strong class="mt-1 block">${esc(label)}</strong><small class="text-slate-500">${esc(sample.requester_phone||'Téléphone non renseigné')}</small></div>`:`<div><strong>${esc(label)}</strong><small class="ml-2 text-slate-400">${items.length} mouvement${items.length>1?'s':''}</small></div>`;return `<section class="treasury-group"><header class="treasury-group-head"><div class="flex items-center gap-3">${identity}</div><div class="text-right"><small class="block text-slate-400">Sous-total</small><strong class="${subtotal>=0?'text-emerald-700':'text-rose-700'}">${subtotal>=0?'+':'−'} ${money(Math.abs(subtotal))}</strong></div></header><div class="treasury-group-body">${items.map(flowRow).join('')}</div></section>`}).join('');document.getElementById('detailContent').innerHTML=`<div class="sticky top-0 z-10 -mx-5 -mt-5 mb-5 border-b bg-white/95 p-5 backdrop-blur"><div class="flex flex-wrap justify-between gap-3"><div><p class="text-sm text-slate-500">${esc(dataset.context)}</p><div class="mt-2 flex flex-wrap gap-2" data-modes>${[['list','Liste'],['allocation','Par affectation'],['beneficiary','Par bénéficiaire'],['requester','Par demandeur']].map(([v,l])=>`<button data-mode="${v}" class="rounded-full px-3 py-2 text-xs font-black ${v===mode?'bg-indigo-700 text-white':'bg-slate-100 text-slate-600'}">${l}</button>`).join('')}</div></div><div class="flex gap-2"><button data-csv class="rounded-xl border bg-white px-3 py-2 text-xs font-black"><i class="fas fa-file-excel mr-1 text-emerald-600"></i>Excel</button><button data-pdf class="rounded-xl bg-rose-700 px-3 py-2 text-xs font-black text-white"><i class="fas fa-file-pdf mr-1"></i>PDF ISO signé</button></div></div><div class="mt-3 grid gap-2 lg:grid-cols-3">${multiPicker('Affectations','allocation',options.allocation,filters.allocation)}${multiPicker('Bénéficiaires','beneficiary',options.beneficiary,filters.beneficiary)}${multiPicker('Demandeurs','requester',options.requester,filters.requester)}</div><div class="mt-3 grid grid-cols-3 gap-2 text-right"><div class="rounded-xl bg-emerald-50 p-2"><small>Entrées</small><b class="block text-emerald-800">${money(incoming)}</b></div><div class="rounded-xl bg-rose-50 p-2"><small>Sorties</small><b class="block text-rose-800">${money(outgoing)}</b></div><div class="rounded-xl bg-indigo-50 p-2"><small>Total net</small><b class="block">${money(incoming-outgoing)}</b></div></div></div><div class="grid gap-4">${sections||'<div class="rounded-2xl bg-white py-14 text-center text-slate-500">Aucun résultat pour ces filtres.</div>'}</div>`;document.querySelectorAll('[data-modes] button').forEach(b=>b.onclick=()=>renderMulti(dataset,b.dataset.mode,filters));document.querySelectorAll('[data-multi-filter]').forEach(root=>{const key=root.dataset.multiFilter,input=root.querySelector('input');input.onchange=()=>{const value=input.value.trim();if(value&&options[key].includes(value)&&!filters[key].includes(value))renderMulti(dataset,mode,{...filters,[key]:[...filters[key],value]});else input.value=''};root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>renderMulti(dataset,mode,{...filters,[key]:filters[key].filter(v=>v!==decodeURIComponent(b.dataset.remove))}))});document.querySelector('[data-csv]').onclick=()=>exportTreasuryCsv(dataset,rows);document.querySelector('[data-pdf]').onclick=()=>{const q=new URLSearchParams({view:dataset.view,from:'<?=$from?>',to:'<?=$to?>',group:mode,allocations:JSON.stringify(filters.allocation),beneficiaries:JSON.stringify(filters.beneficiary),requesters:JSON.stringify(filters.requester)});window.open('request/export_treasury_pdf.php?'+q.toString(),'_blank')}}
document.querySelectorAll('[data-detail]').forEach(button=>button.onclick=()=>{const dataset=detailDataset(button.dataset.detail);dataset.view=button.dataset.detail;document.getElementById('detailTitle').textContent=dataset.title;renderMulti(dataset);open('detailModal')});})();
</script>
